{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Glimepiride, the closest analogue sharing the sulfonylurea-cyclohexyl urea and phenethyl linker, had an absolute oral bioavailability of 97% (90% CI 93-102%) in healthy male volunteers after tablet vs IV dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Glimepiride tablet was completely bioavailable in healthy volunteers, confirming essentially complete oral absorption for this sulfonylurea scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "PF-05150122, a high-transfer sulfonamide-containing oral compound, showed 52% absolute oral bioavailability in a human microdose study, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Bosentan, a sulfonamide-containing oral drug with high transfer, had mean absolute bioavailability of approximately 50% in healthy male subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Verapamil, a lipophilic aromatic oral drug with a basic amine, had 49 ± 14% absolute bioavailability in healthy men, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Agomelatine had absolute bioavailability <5%, but it lacks the sulfonylurea/cyclohexyl urea features and has much lower transfer, so this contradictory evidence is outweighed.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a sulfonylurea closely related to glimepiride, whose absolute oral bioavailability is ~97-100%; additional high-transfer analogues (PF-05150122 52%, bosentan ~50%, verapamil ~34-49%) all exceed 20%. Low-F analogues are structurally distant and lower-transfer, so the prediction is high.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself.",
    "The closest analogue glimepiride differs in the acyl substituent and cyclohexyl methylation; the impact of these changes on absorption is not directly measured.",
    "Human absolute bioavailability data for the exact query are absent; transfer relies on analogue evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

